import pytest
from toplam import toplam

def test_toplam_basic():
    assert toplam([1, 2, 3, 4]) == 10

def test_toplam_empty():
    assert toplam([]) == 0

def test_toplam_negative():
    assert toplam([-1, 5, -3]) == 1

def test_toplam_floats():
    assert toplam([1.5, 2.5, 3.0]) == 7.0

